<?php
$kpiRecords=[];
foreach($farm['slaughters'] as$s){
    if(in_array($s['status'],['submitted','validated'],true))$kpiRecords[]=['kind'=>$s['status'],'reference'=>$s['conversion_number'],'lot'=>$s['batch_number'],'site'=>$s['site_name'],'date'=>$s['converted_at'],'heads'=>(int)$s['input_heads'],'weight'=>(float)$s['net_weight_kg'],'expiry'=>$s['expiry_date'],'state'=>$statusLabels[$s['status']],'detail'=>'Enregistré par '.$s['author'].($s['validator']?' · Validé par '.$s['validator']:'')];
    if($s['status']==='validated'&&(float)$s['quantity_kg']>0)$kpiRecords[]=['kind'=>'stock','reference'=>$s['conversion_number'],'lot'=>$s['batch_number'],'site'=>$s['site_name'],'date'=>$s['converted_at'],'heads'=>null,'weight'=>(float)$s['quantity_kg'],'expiry'=>$s['expiry_date'],'state'=>$s['expiry_date']<date('Y-m-d')?'DLC dépassée':'Stock ferme','detail'=>$kg($s['reserved_kg']).' kg réservés · '.$kg((float)$s['quantity_kg']-(float)$s['reserved_kg']).' kg non réservés'];
}
foreach($farm['shipments'] as$t)$kpiRecords[]=['kind'=>'shipment','reference'=>$t['transfer_number'],'lot'=>$t['batch_number'],'site'=>'Vers la boucherie','date'=>$t['created_at']??'','heads'=>null,'weight'=>(float)$t['quantity_kg'],'expiry'=>$t['expiry_date'],'state'=>$statusLabels[$t['status']]??$t['status'],'detail'=>$t['truck_plate'].' · '.$t['driver_name']];
?>
<section id="flow-kpi-detail" class="entity-modal workspace-entity-modal feed-editor flow-kpi-detail" role="dialog" aria-modal="true" aria-hidden="true" aria-labelledby="flow-kpi-title">
<header><div><p class="page-kicker">PORCS · FERME</p><h2 id="flow-kpi-title">Détails</h2><p data-kpi-total></p></div><button type="button" class="modal-close" data-workspace-modal-close aria-label="Fermer les détails">×</button></header>
<div class="feed-form-body">
<div class="ui-filterbar"><label class="ui-filterbar__search"><span>Rechercher dans ces détails</span><input type="search" data-kpi-search placeholder="Numéro, lot, ferme, chauffeur…"></label><label><span>Lignes par page</span><select data-kpi-size><option value="10">10</option><option value="25">25</option><option value="50">50</option></select></label></div>
<div class="table-responsive slaughter-table-wrap"><table class="enterprise-table slaughter-table" data-datatable="false" aria-label="Détails de l’indicateur"><thead><tr><?php foreach(['reference'=>'Référence / lot','date'=>'Date','heads'=>'Porcs','weight'=>'Poids (kg)','expiry'=>'DLC','state'=>'État'] as$key=>$label):?><th scope="col" aria-sort="none"><button type="button" data-kpi-sort="<?=e($key)?>"><?=e($label)?> <span aria-hidden="true">↕</span></button></th><?php endforeach;?><th scope="col">Informations</th></tr></thead><tbody>
<?php foreach($kpiRecords as$r):?><tr data-kpi-record data-category="<?=e($r['kind'])?>" data-reference="<?=e($r['reference'])?>" data-date="<?=e($r['date'])?>" data-heads="<?=e($r['heads']??0)?>" data-weight="<?=e($r['weight'])?>" data-expiry="<?=e($r['expiry'])?>" data-state="<?=e($r['state'])?>" data-search="<?=e(implode(' ',array_filter($r,'is_scalar')))?>">
<td data-label="Référence / lot"><strong><?=e($r['reference'])?></strong><small><?=e($r['site'])?></small><small><?=e($r['lot'])?></small></td><td data-label="Date"><?=$r['date']?e(date('d/m/Y H:i',strtotime($r['date']))):'—'?></td><td class="num" data-label="Porcs"><?=$r['heads']===null?'—':$r['heads']?></td><td class="num" data-label="Poids (kg)"><?=$kg($r['weight'])?></td><td data-label="DLC"><?=e(date('d/m/Y',strtotime($r['expiry'])))?></td><td data-label="État"><?=e($r['state'])?></td><td data-label="Informations"><?=e($r['detail'])?></td></tr><?php endforeach;?>
</tbody></table></div><p class="flow-empty" data-kpi-empty hidden>Aucun résultat pour cette sélection.</p><div class="campaign-pagination slaughter-pagination"><span data-kpi-count role="status"></span><div><button type="button" class="btn-secondary" data-kpi-page="-1">Précédent</button><span data-kpi-page-label></span><button type="button" class="btn-secondary" data-kpi-page="1">Suivant</button></div></div>
</div></section>
